from pathlib import Path
from html import escape as e
import json
r=Path(__file__).resolve().parents[1]; apps=json.loads((r/'data/flows.json').read_text()); sources=json.loads((r/'research/sources.json').read_text())
sources.update(json.loads((r/'research/motion-sources.json').read_text()))
def motion_section(a):
 m=a['motion']
 out=f'<section class="reference-section motion-section" id="motion"><p class="eyebrow">{e(a["name"]).upper()} / MOTION / ROLLOVER / ASSET DIRECTION</p><h2>{e(m["title"])}</h2><p class="motion-lede">{e(m["overview"])}</p><p class="motion-method">{e(m["method"])}</p><p class="small">A specification for the next build. Animation, video and extracted objects are described here; these review screens remain still images.</p><div class="actions"><a class="pill solid" href="../{m["path"]}" download>Motion brief .md ↓</a><a class="pill" href="../{m["prompt_path"]}" download>Interaction prompt ↓</a><a class="textlink" href="../research/motion-references.md">Reference index ↗</a></div>'
 out+='<div class="motion-principles">'+''.join(f'<article><p class="eyebrow">{title}</p><p>{e(m["shared"][key])}</p></article>' for title,key in [('ROLLOVER & TOUCH','input_policy'),('TIMING & FEEDBACK','timing'),('REDUCED MOTION','reduced')])+'</div>'
 out+='<h3>Across the five screens.</h3><div class="motion-sequence">'
 for s in a['screens']:
  out+=f'<article><p class="eyebrow">{s["number"]:02d} / {e(s["phase"])}</p><h3>{e(s["title"])}</h3><p><b>In the background.</b> {e(s["motion"]["ambient"])}</p><p><b>On interaction.</b> {e(s["motion"]["action"])}</p><p><b>Scroll & return.</b> {e(s["motion"]["scroll"])}</p><a href="../{s["interaction_prompt_path"]}" download>Screen interaction prompt ↓</a></article>'
 out+='</div><div class="motion-build"><div><p class="eyebrow">ASSETS TO PREPARE</p><ul>'+''.join('<li>'+e(x)+'</li>' for x in m['assets'])+f'</ul><a class="textlink" href="../{m["asset_prompt_path"]}" download>Asset extraction prompt ↓</a></div><div><p class="eyebrow">HOW IT BECOMES REACT</p><p>{e(m["production"])}</p></div></div>'
 for title,key in [('App interaction prompt','interaction_prompt'),('Asset extraction / reconstruction prompt','extraction'),('Motion direction prompt','motion_prompt')]:out+=f'<details class="motion-prompt"><summary>{title}</summary><pre>{e(m[key])}</pre></details>'
 out+='<details><summary>Lifecycle, fallback and acceptance</summary>'+''.join('<p>'+e(m['shared'][k])+'</p>' for k in ['ambient','scroll','runtime','verification'])+'</details><h3 class="motion-ref-title">References behind the motion.</h3><div class="source-grid">'
 for src in m['references']:out+=f'<article><a href="{e(src["url"])}" target="_blank" rel="noopener">{e(src["title"])} ↗</a><p>{e(src["finding"])}</p></article>'
 return out+'</div><p class="small">The six app directions, timings and effect amplitudes are WDA proposals. “VO” is interpreted as Veo for visual motion studies; no voiceover is planned. Soul, Petal and Daybook use programmatic production animation.</p></section>'
def shell(title,body,prefix='',data=None):
 payload=('<script id="review-data" type="application/json">'+json.dumps(data,ensure_ascii=False).replace('</','<\\/')+'</script>') if data else ''
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Jason Festa / WDA. Six app directions, thirty mobile screens, research and interaction specifications."><title>{e(title)} · WDA</title><link rel="stylesheet" href="{prefix}style.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="top"><a class="brand" href="{prefix}index.html">WDA <span>/ APP STUDY</span></a><span>JASON FESTA <span class="date">/ OCTOBER 2026</span></span></header><main id="main">{body}</main><footer><span>WDA / Jason Festa</span><a href="{prefix}index.html">All six studies ↑</a></footer>{payload}<script src="{prefix}study.js" defer></script></body></html>'''
def card(app,s,prefix='',review=False):
 href=('#'+s['id']) if review else f'reviews/{app["id"]}.html#{s["id"]}'
 return f'''<figure class="screen-card"><a href="{href}" {'data-select="'+s['id']+'"' if review else ''}><div class="screen-label"><span>{s['number']:02d} / {e(s['phase'])}</span><span>↗</span></div><img src="{prefix+s['image']}" alt="{e(app['name']+' — '+s['title'])}" loading="lazy" width="{s['native_size'][0]}" height="{s['native_size'][1]}"><figcaption>{e(s['title'])}</figcaption></a></figure>'''
body='''<section class="hero"><p class="eyebrow">MOBILE EXPERIENCES / FLOWS & MOTION</p><h1>Little worlds.<br><em>Complete journeys.</em></h1><div class="hero-bottom"><p>Six distinct app directions, carried from a first hello into everyday use. Five screens each, with clean app-only exports, research, interaction prompts and a motion direction for every screen.</p><div class="metric"><b>06 / 30</b><span>APPS / MOBILE SCREENS</span></div></div><div class="actions"><a class="pill solid" href="downloads/app-study-images.zip" download>Download 30 screens ↓</a><a class="pill" href="downloads/app-study-reference-pack.zip" download>MD + reference pack ↓</a><a class="textlink" href="research.html">Research & handoff ↗</a></div></section>'''
body+='<nav class="app-nav" aria-label="App studies">'+''.join(f'<a href="#{a["id"]}">{i+1:02d} {e(a["name"])}</a>' for i,a in enumerate(apps))+'</nav>'
for i,a in enumerate(apps):
 desc={'afterglow':'A softer evening, from choosing a rhythm to finding a ritual and pressing play.','pocket-garden':'One little plant, an attentive check-in, and room for the things you notice.','home-note':'A shared home with clear handovers, useful notes, and people who know the plan.','soul':'Weather with a lighter touch. A city, a forecast, and the preferences that make it yours.','petal':'Botanical pieces become a quiet daily practice, from first move to a growing collection.','daybook':'Make space for daylight, adjust a plan, and see an open week ahead.'}[a['id']]
 body+=f'<section class="app-section" id="{a["id"]}"><div class="section-heading"><div><p class="eyebrow">STUDY {i+1:02d} / 05 SCREENS</p><h2>{e(a["name"])}</h2><p>{desc}</p></div><a class="pill" href="reviews/{a["id"]}.html">Flow & interaction review ↗</a></div><div class="screen-grid">'+''.join(card(a,s) for s in a['screens'])+f'</div><div class="row-links"><a href="interaction/{a["id"]}.md" download>Interaction ledger .md ↓</a><a href="reviews/{a["id"]}.html#motion">Motion & rollover ↗</a><a href="reviews/{a["id"]}.html#references">Prompts & references ↗</a></div></section>'
body+='<section class="closing"><p class="eyebrow">THE NEXT LAYER</p><h2>Every action has<br><em>a place to go.</em></h2><p>Each review includes the pictured sequence, a control-by-control action explorer, additional routes, recovery states, a motion brief, asset extraction prompts, and a React handoff. Alternative approaches are documented alongside the primary flow.</p><a class="pill solid" href="research.html">Read the research & handoff ↗</a><a class="pill" href="downloads/app-study.zip" download>Download complete study ↓</a></section>'
(r/'index.html').write_text(shell('App study',body))
for a in apps:
 body=f'<section class="review-hero"><a class="back" href="../index.html#{a["id"]}">← All app studies</a><p class="eyebrow">FLOW / VISUALS / INTERACTION</p><h1>{e(a["name"])}</h1><p class="lede">{e(a["decision"])}</p><div class="actions"><a class="pill" href="../interaction/{a["id"]}.md" download>Download interaction MD ↓</a><a class="textlink" href="#motion">Motion & rollover ↓</a><a class="textlink" href="#references">Prompts & references ↓</a><a class="textlink" href="../research.html">Shared React handoff ↗</a></div></section>'
 body+='<section aria-label="Five-screen sequence"><div class="screen-grid review-rail">'+''.join(card(a,s,'../',True) for s in a['screens'])+'</div></section>'
 body+='''<section class="walkthrough" id="walkthrough"><div class="walk-intro"><p class="eyebrow">ACTION / INTERACTION EXPLORER</p><h2 id="screen-title"></h2><p id="screen-entry"></p><p class="small">Choose a screen, then a control to read its behavior. These are reference states; this walkthrough does not save app data or trigger permissions.</p><div class="step-controls"><button id="previous" type="button">← Previous</button><span id="screen-position"></span><button id="next" type="button">Next →</button></div></div><div class="walk-body"><div class="preview"><a id="full-image" target="_blank" rel="noopener"><img id="active-screen" alt=""></a><a class="textlink" id="download-screen" download>Download this screen ↓</a><p class="small" id="image-size"></p></div><div class="interaction-panel"><p class="eyebrow">ON THIS SCREEN</p><div id="control-list"></div><section id="control-result" class="control-result" aria-live="polite"><p>Select a control to inspect its route and behavior.</p></section><section class="screen-motion"><p class="eyebrow">THIS SCREEN / MOTION DIRECTION</p><p id="ambient-notes"></p><p id="action-notes"></p><a id="interaction-prompt" class="textlink" download>Screen interaction prompt ↓</a></section><details><summary>Scroll, hover & reduced motion</summary><p id="scroll-notes"></p><p id="hover-notes"></p></details><details><summary>Display-only elements</summary><p id="display-notes"></p></details></div></div></section>'''
 body+=motion_section(a)
 body+='<section class="reference-section"><p class="eyebrow">STATE & RETURN PATHS</p><h2>A flow that holds together.</h2><p>'+e(a['fixture'])+'</p><ul class="checks">'+''.join('<li>'+e(x)+'</li>' for x in a['checks'])+'</ul><div class="branch-grid">'+''.join(f'<details id="aux-{k}"><summary>{e(k.replace("-"," ").title())}</summary><p>{e(v)}</p></details>' for k,v in a['auxiliary_routes'].items())+'</div></section>'
 alt=a['alternatives'][0]; body+=f'<section class="alternative"><p class="eyebrow">ALTERNATIVE TO EVALUATE</p><h2>{e(alt["title"])}</h2><p>{e(alt["detail"])}</p><p class="small">A proposed route variation, documented for comparison. It does not add another image to the five-screen export.</p></section>'
 body+=f'<section class="reference-section" id="references"><p class="eyebrow">PROMPTS / PROVENANCE / BUILD REFERENCES</p><h2>The thinking beneath<br><em>the screens.</em></h2><div class="source-layout"><div><img class="original" src="../references/originals/{a["original"]}.png" alt="Original {e(a["name"])} art-direction reference" loading="lazy"><p class="small">Original art direction, retained as reference. Current exports have square edges, no exterior presentation margin and no OS chrome. This historical source is unchanged.</p><a href="../prompts/{a["original"]}.txt">Original prompt ↗</a></div><div><p>{e(a["style"])}</p><p>Type direction: {e(", ".join(a["fonts"]))}.</p><div class="swatches">'+''.join(f'<span style="--swatch:{color}">{color}</span>' for color in a['palette'])+'</div><p class="small">The original screenshots establish visual direction. Official product documentation supports the feature research; detailed routes and motion are proposed WDA decisions.</p><ul class="source-list">'
 for key in a['sources']:
  src=sources[key];body+=f'<li><a href="{e(src["url"])}" target="_blank" rel="noopener">{e(src["title"])} ↗</a><p>{e(src["finding"])}</p></li>'
 body+='</ul><a class="textlink" href="../research/README.md">Packaged research index .md ↗</a></div></div><div class="prompts">'
 for s in a['screens']:body+=f'<details><summary>{s["number"]:02d} / {e(s["title"])} — exact prompt</summary><p><a href="../{s["prompt"]}" download>Download prompt ↓</a></p><pre>{e(s["exact_prompt"])}</pre></details>'
 body+='</div></section>'
 (r/f'reviews/{a["id"]}.html').write_text(shell(a['name']+' review',body,'../',a))
 (r/f'reviews/{a["id"]}.md').write_text((r/f'interaction/{a["id"]}.md').read_text().replace('(react-handoff.md)','(../interaction/react-handoff.md)').replace('(motion/','(../interaction/motion/'))
body='''<section class="review-hero"><a class="back" href="index.html">← App study</a><p class="eyebrow">RESEARCH / INTERACTION / REACT</p><h1>From reference<br><em>to behavior.</em></h1><p class="lede">Original art direction, archived research, and a specific plan for each screen. Product documentation supports the feature direction; the interaction decisions below are proposed for these six experiences.</p><div class="actions"><a class="pill solid" href="downloads/app-study-reference-pack.zip" download>Download MD + references ↓</a><a class="pill" href="interaction/react-handoff.md" download>React handoff .md ↓</a></div></section><section class="reference-section"><h2>The six control ledgers.</h2><div class="ledger-grid">'''
for a in apps:body+=f'<article><p class="eyebrow">{sum(len(s["controls"])+len(s["shared_controls"]) for s in a["screens"])} CONTROL / NAVIGATION ENTRIES</p><h3>{e(a["name"])}</h3><p>{e(a["decision"])}</p><a href="reviews/{a["id"]}.html">Open visual review ↗</a><a href="interaction/{a["id"]}.md" download>Download MD ↓</a></article>'
body+='</div></section><section class="reference-section"><h2>Motion belongs to the experience.</h2><p>Afterglow’s light shader, living illustrations for Pocket Garden and Home Note, reconstructed 3D weather for Soul, and programmatic puzzles and daylight for Petal and Daybook. Each direction includes five screen behaviors, rollover rules, prompts and build references.</p><p><a href="research/motion-references.md">Motion research and six briefs .md ↗</a></p></section><section class="reference-section"><h2>What carries into React.</h2><div class="ledger-grid"><article><h3>Routes & state</h3><p>Explicit destinations, return routes and record IDs. Drafts stay separate from saved data. Shared selectors drive counts, durations and progress.</p></article><article><h3>Every input</h3><p>Touch, keyboard, focus and hover. Each action has feedback, a destination and a recovery route. Decorative artwork is identified separately.</p></article><article><h3>Beyond the happy path</h3><p>Back, cancel, retries, offline states, permission refusal, duplicate saves and accessible alternatives to dragging.</p></article></div><p><a href="interaction/react-handoff.md">Read the complete implementation contract .md ↗</a></p></section><section class="reference-section"><h2>Reference library.</h2><p class="small">Checked 21 October 2026. Native Mobbin flows were unavailable through the connected service’s paid-plan restriction; no Mobbin results are used. The Apple onboarding article was only partially accessible and supports no attributed behavior here.</p><div class="source-grid">'
for src in sources.values():body+=f'<article><a href="{e(src["url"])}" target="_blank" rel="noopener">{e(src["title"])} ↗</a><p>{e(src["finding"])}</p></article>'
body+='</div><h3>Saved workspace research</h3><p><a href="research/archive/mobile-research-2026-10-20.md">Mobile research .md</a> · <a href="research/archive/mobile-state-plan-2026-10-20.md">Earlier state matrix .md</a> · <a href="research/archive/expanded-flow-research-2026-10-20.md">Expanded flow research .md</a></p></section>'
(r/'research.html').write_text(shell('Research & handoff',body))
print('Built overview, six reviews and research page')
